import { useNavigate } from "react-router-dom";


export default function Navig() {
  const navigate = useNavigate();

  const onHome = () => {
    navigate(`/portfolio`);
  };
  const onPortfolio = () => {
    navigate(`/portfolio`);
  };


return (  
<div className="header__nav">
    <div className="header__nav-nav">
      <ul>
        <li><p>home</p></li>
        <li onClick={onPortfolio}><p>portfolio</p></li>
        <li><p>contacts</p></li>
      </ul>
    </div>
  </div>
  
);
}
